using Kordra.Modules.ProjectEnvironment.Contracts;
using Kordra.Modules.ProjectEnvironment.Infrastructure;
using Microsoft.EntityFrameworkCore;

namespace Kordra.Modules.ProjectEnvironment;

public sealed class ProjectIdentityReader(ProjectDbContext db) : IProjectIdentityReader
{
    public async Task<ProjectIdentity?> ReadCurrentProjectUnderAdmissionAsync(Guid projectId, CancellationToken ct = default)
    {
        if (projectId == Guid.Empty) return null;
        // IDs are generated by the owner, but the historical PK is (tenant,id). Do not
        // silently select one tenant, even when a colliding row is inactive/deleted.
        var matches = await db.Projects.AsNoTracking().Where(p => p.Id == projectId).Take(2).ToArrayAsync(ct);
        if (matches.Length != 1 || matches[0].Status != "active" || matches[0].TenantId == Guid.Empty || matches[0].Revision <= 0)
            return null;
        return new(matches[0].TenantId, matches[0].Id, matches[0].Revision);
    }
}
